import json
import sys
sys.path.insert(0, '/workspace')
from rewards.list_functions import score_program

def _eval_program(src, inputs, outputs):
    ns = {}
    try:
        exec(src, {"__builtins__": __builtins__}, ns)
    except SyntaxError:
        return 0.0, ["syntax error"]
    fn = ns.get("program") or ns.get("solve") or ns.get("f") or ns.get("transform")
    if fn is None:
        return 0.0, ["no function found"]
    return score_program(fn, inputs, outputs)

def _unique_list(lst):
    if not lst: return []
    out = [lst[0]]
    for x in lst[1:]:
        if x != out[-1]: out.append(x)
    return out

def _all_thresholds(inputs):
    vals = set()
    for xs in inputs: vals.update(xs)
    return sorted(vals)

# SLICES
def _candidate_slices(inputs):
    cands = []
    lengths = set(len(xs) for xs in inputs)
    max_len = max(lengths) if lengths else 10
    thresholds = list(range(0, max(max_len + 1, 5)))
    for N in thresholds:
        if N == 0: continue
        cands.append((f"def program(xs):\n    return xs[:{N}]\n", f"first {N}"))
        cands.append((f"def program(xs):\n    return xs[-{N}:]\n", f"last {N}"))
        cands.append((f"def program(xs):\n    return xs[{N}:]\n", f"from index {N}"))
        for M in thresholds:
            if M > 0:
                cands.append((f"def program(xs):\n    return xs[{N}:-{M}]\n", f"xs[{N}:-{M}]"))
        for k in range(2, max_len + 1):
            cands.append((f"def program(xs):\n    return xs[::{k}]\n", f"every {k}th"))
            for offset in range(1, k):
                cands.append((f"def program(xs):\n    return xs[{offset}::{k}]\n", f"xs[{offset}::{k}]"))
    return cands

# FILTERS
def _candidate_filters(inputs):
    cands = []
    thresholds = _all_thresholds(inputs)
    for t in [0, 1, 2, 3, 5, 10, 20, 50, 100]:
        if t not in thresholds: thresholds.append(t)
    thresholds = sorted(set(thresholds))
    for t in thresholds:
        if t > 0:
            cands.append((f"def program(xs):\n    return [x for x in xs if x >= {t}]\n", f"filter x >= {t}"))
        cands.append((f"def program(xs):\n    return [x for x in xs if x > {t}]\n", f"filter x > {t}"))
        if t > 0:
            cands.append((f"def program(xs):\n    return [x for x in xs if x <= {t}]\n", f"filter x <= {t}"))
        cands.append((f"def program(xs):\n    return [x for x in xs if x < {t}]\n", f"filter x < {t}"))
        cands.append((f"def program(xs):\n    return [x for x in xs if x == {t}]\n", f"filter x == {t}"))
    for k in range(2, 6):
        cands.append((f"def program(xs):\n    return [x for x in xs if x % {k} != 0]\n", f"filter x % {k} != 0"))
        cands.append((f"def program(xs):\n    return [x for x in xs if x % {k} == 0]\n", f"filter x % {k} == 0"))
    cands.append(("def program(xs):\n    return [x for x in xs if x != 0]\n", "filter x != 0"))
    cands.append(("def program(xs):\n    seen = set()\n    out = []\n    for x in xs:\n        if x not in seen:\n            seen.add(x)\n            out.append(x)\n    return out\n", "unique order-preserving"))
    cands.append(("def program(xs):\n    return _unique_list(xs)\n", "remove consecutive duplicates"))
    return cands

# SORTING
def _candidate_sorting(inputs):
    cands = []
    lengths = set(len(xs) for xs in inputs)
    max_len = max(lengths) if lengths else 10
    for N in range(1, min(max_len + 1, 10)):
        cands.append((f"def program(xs):\n    return sorted(xs)[:{N}]\n", f"smallest {N} sorted"))
        cands.append((f"def program(xs):\n    return sorted(xs)[-{N}:]\n", f"largest {N} sorted"))
    cands.append(("def program(xs):\n    return sorted(xs)\n", "sorted"))
    cands.append(("def program(xs):\n    return list(reversed(xs))\n", "reversed"))
    cands.append(("def program(xs):\n    return sorted(xs, reverse=True)\n", "sorted desc"))
    cands.append(("def program(xs):\n    return sorted(xs)[::-1]\n", "sorted reversed"))
    return cands

# POSITIONAL
def _candidate_positional(inputs):
    cands = []
    lengths = set(len(xs) for xs in inputs)
    max_len = max(lengths) if lengths else 10
    thresholds = list(range(0, min(max_len + 1, 8)))
    for N in thresholds:
        if N == 0: continue
        cands.append((f"def program(xs):\n    return xs[:{N}] + xs[{N+1}:]\n", f"delete index {N}"))
    cands.append(("def program(xs):\n    if not xs: return []\n    return [xs[-1]] + xs[1:]\n", "replace first with last"))
    for c in range(10):
        cands.append((f"def program(xs):\n    if not xs: return []\n    return [{c}] + xs[1:]\n", f"replace first with {c}"))
    for N in thresholds:
        if N == 0: continue
        cands.append((f"def program(xs):\n    if not xs: return []\n    return xs[:{N}] + [xs[-1]] + xs[{N+1}:]\n", f"replace index {N} with last"))
    cands.append(("def program(xs):\n    if len(xs) <= 1: return xs\n    return xs[1:] + [xs[0]]\n", "move first to end"))
    cands.append(("def program(xs):\n    if len(xs) <= 1: return xs\n    return [xs[-1]] + xs[1:-1] + [xs[0]]\n", "swap first and last"))
    for N in range(1, 4):
        cands.append((f"def program(xs):\n    if len(xs) <= {N}: return xs\n    return xs[-{N}:] + xs[:-{N}]\n", f"rotate right by {N}"))
    for N in range(1, 4):
        cands.append((f"def program(xs):\n    if len(xs) <= {N}: return xs\n    return xs[{N}:] + xs[:{N}]\n", f"rotate left by {N}"))
    return cands

# APPEND/PREPEND
def _candidate_append(inputs):
    cands = []
    for c in range(10):
        cands.append((f"def program(xs):\n    return xs + [{c}]\n", f"append {c}"))
        cands.append((f"def program(xs):\n    return [{c}] + xs\n", f"prepend {c}"))
    cands.append(("def program(xs):\n    if not xs: return xs\n    return xs + [xs[-1]]\n", "append last"))
    cands.append(("def program(xs):\n    if not xs: return xs\n    return [xs[0]] + xs\n", "prepend first"))
    cands.append(("def program(xs):\n    return xs + xs\n", "double"))
    cands.append(("def program(xs):\n    return [i for i in range(len(xs))]\n", "indices"))
    cands.append(("def program(xs):\n    return [len(xs)-1-i for i in range(len(xs))]\n", "reversed indices"))
    return cands

# ARITHMETIC
def _candidate_arithmetic(inputs):
    cands = []
    cands.append(("def program(xs):\n    return [x * 2 for x in xs]\n", "double each"))
    cands.append(("def program(xs):\n    return [x * 3 for x in xs]\n", "triple each"))
    cands.append(("def program(xs):\n    return [x // 2 for x in xs]\n", "halve each"))
    for c in range(1, 6):
        cands.append((f"def program(xs):\n    return [x + {c} for x in xs]\n", f"add {c}"))
    cands.append(("def program(xs):\n    return [abs(x) for x in xs]\n", "abs"))
    cands.append(("def program(xs):\n    return [int(x**0.5) for x in xs]\n", "int sqrt"))
    cands.append(("def program(xs):\n    return [sum(xs)]\n", "sum"))
    cands.append(("def program(xs):\n    return [min(xs)] if xs else []\n", "min"))
    cands.append(("def program(xs):\n    return [max(xs)] if xs else []\n", "max"))
    cands.append(("def program(xs):\n    return [len(xs)]\n", "length"))
    cands.append(("def program(xs):\n    acc = 0\n    return [acc := acc + x for x in xs]\n", "cumsum"))
    cands.append(("def program(xs):\n    return [xs[i+1] - xs[i] for i in range(len(xs)-1)]\n", "diffs"))
    return cands

# SPECIAL PATTERNS
def _candidate_special(inputs, outputs):
    cands = []

    # Single element output - count occurrences
    if all(len(ys) == 1 for ys in outputs) and outputs:
        cands.append(("def program(xs):\n    if not xs: return []\n    return [xs.count(xs[0]) - 1]\n", "count first-1"))
        cands.append(("def program(xs):\n    if not xs: return []\n    return [xs.count(xs[0])]\n", "count first"))
        cands.append(("def program(xs):\n    if not xs: return []\n    return [xs.count(xs[-1])]\n", "count last"))

    # Remove first
    for inp, out in zip(inputs, outputs):
        if out == inp[1:]:
            cands.append(("def program(xs):\n    return xs[1:]\n", "remove first"))
            break

    # Remove last
    for inp, out in zip(inputs, outputs):
        if out == inp[:-1]:
            cands.append(("def program(xs):\n    return xs[:-1]\n", "remove last"))
            break

    # Reverse
